"""Generate the Freya workflows for brief-a-raw (one product) and brief-b-raw (one to three products).

    python3 out/generate.py

Writes out/brief-a-raw.workflow.json, out/brief-b-raw.workflow.json and their contracts.
Every value below comes from briefs/brief-a-raw.md, briefs/brief-b-raw.md and tools/openapi.json.
"""
import json
from pathlib import Path

ROOT = Path(__file__).resolve().parent.parent
API = json.loads((ROOT / "tools/openapi.json").read_text())
SERVER = API["servers"][0]["url"].rstrip("/")

# ----------------------------------------------------------------------------- code step (dates, products, offers)
# Runs twice: once at call start (dates, callback window), once after get_account (products and offers).
# Must contain no double braces. Reads and writes only through vars.
PLAN_CODE = r'''
import datetime, json, re

HOLIDAYS = ["2026-10-26", "2026-11-11", "2026-11-26", "2026-12-25", "2027-01-01"]
HOL = set(datetime.date.fromisoformat(h) for h in HOLIDAYS)
WD = ["Monday", "Tuesday", "Wednesday", "Thursday", "Friday", "Saturday", "Sunday"]
MO = ["January", "February", "March", "April", "May", "June", "July", "August", "September", "October", "November", "December"]

def speak(d):
    return WD[d.weekday()] + " " + str(d.day) + " " + MO[d.month - 1] + " " + str(d.year) + " (" + d.isoformat() + ")"

def is_bd(d):
    return d.weekday() < 5 and d not in HOL

def nth_bd_after(d, n):
    k = 0
    while n > 0:
        k += 1
        if is_bd(d + datetime.timedelta(days=k)):
            n -= 1
    return d + datetime.timedelta(days=k)

def next_bd_on_or_after(d):
    while not is_bd(d):
        d = d + datetime.timedelta(days=1)
    return d

def last_bd_of_week(monday):
    for k in range(4, -1, -1):
        d = monday + datetime.timedelta(days=k)
        if is_bd(d):
            return d
    return None

def money(x):
    try:
        return "{:,.2f}".format(float(x))
    except Exception:
        return str(x)

def num(x):
    try:
        return "{:.2f}".format(float(x))
    except Exception:
        return str(x)

def parse_now(s):
    s = str(s or "").strip()
    for cut in (16, 19, 10):
        try:
            v = datetime.datetime.fromisoformat(s[:cut])
            if cut == 10:
                v = v.replace(hour=9, minute=0)
            return v
        except Exception:
            pass
    return None

def load_products():
    raw = vars.get("products")
    if isinstance(raw, str):
        t = raw.strip()
        for cand in (t, t.replace("'", '"').replace("None", "null").replace("True", "true").replace("False", "false")):
            try:
                raw = json.loads(cand)
                break
            except Exception:
                pass
    if isinstance(raw, dict):
        raw = raw.get("products", raw)
    if isinstance(raw, list) and raw and all(isinstance(p, dict) for p in raw):
        return raw
    found = {}
    pat = re.compile(r"products\.(\d+)\.([A-Za-z_0-9]+)$")
    for k, v in list(vars.items()):
        m = pat.search(str(k))
        if m and "get_account" in str(k) or (m and "load_account" in str(k)):
            found.setdefault(int(m.group(1)), {})[m.group(2)] = v
    return [found[i] for i in sorted(found)]

now = parse_now(vars.get("now"))
if now is None:
    now = datetime.datetime(2026, 10, 14, 11, 0)
today = now.date()
monday = today - datetime.timedelta(days=today.weekday())

# first persuasion attempt date: last business day of this week, or of next week when today is that day (or later)
lbd = last_bd_of_week(monday)
if lbd is None or lbd <= today:
    lbd = last_bd_of_week(monday + datetime.timedelta(days=7))
vars["first_attempt_date"] = speak(lbd)
vars["today_text"] = "Now is " + speak(today) + ", " + now.strftime("%H:%M") + "."

# callback window (CP-4 2.2 b as changed by memo item 2): today or the next business day, 10:00 to 19:00, later than now
nbd = next_bd_on_or_after(today + datetime.timedelta(days=1))
cb = []
if now.hour < 19:
    start = "10:00" if now.hour < 10 else now.strftime("%H:%M")
    rule = "from 10:00" if now.hour < 10 else "strictly later than " + start
    cb.append("- Today, " + speak(today) + ": " + rule + " and no later than 19:00. Send date " + today.isoformat() + ".")
else:
    cb.append("- Today, " + speak(today) + ": no longer possible, it is after 19:00.")
cb.append("- Next business day, " + speak(nbd) + ": from 10:00 to 19:00, both included. Send date " + nbd.isoformat() + ".")
cb.append("- Any other day, or any time before 10:00 or after 19:00, is outside the window.")
vars["callback_text"] = "\n".join(cb)
vars["callback_today"] = today.isoformat()
vars["callback_next_bd"] = nbd.isoformat()

products = []
try:
    products = load_products()
except Exception:
    products = []

lines, present, deadlines = [], [], []
count = 0
for i, p in enumerate(products[:3], 1):
    try:
        kind = str(p.get("type") or "")
        if kind == "credit_card":
            words = "credit card ending " + str(p.get("card_last4") or "")
            floor = p.get("minimum_payment")
            floor_name = "minimum payment"
        elif kind == "car_loan":
            words, floor, floor_name = "car loan", p.get("instalment_amount"), "instalment"
        else:
            words, floor, floor_name = "personal loan", p.get("instalment_amount"), "instalment"
        days = int(float(p.get("days_late") or 0))
        late = days >= 8
        stage = "late (8-45 days past due)" if late else "early (1-7 days past due)"
        deadline = nth_bd_after(today, 7 if late else 12)
        attempts = 2 if late else 1
        full = p.get("past_due")
        deadlines.append(deadline)
        count += 1
        vars["p%d_id" % i] = str(p.get("product_id") or "")
        vars["p%d_words" % i] = words
        vars["p%d_past_due_text" % i] = money(full)
        vars["p%d_days_late" % i] = str(days)
        vars["p%d_deadline" % i] = deadline.isoformat()
        t = []
        t.append("PRODUCT %d: %s. product_id: %s." % (i, words, vars["p%d_id" % i]))
        t.append("  Full past-due amount: %s (send as %s). Days late: %d. Stage: %s." % (money(full), num(full), days, stage))
        t.append("  Floor (%s): %s (send as %s)." % (floor_name, money(floor), num(floor)))
        t.append("  PTP deadline: %s. No PTP date after it." % speak(deadline))
        t.append("  Persuasion attempts for this product: %d." % attempts)
        t.append("  Attempt 1: the full amount %s on %s. If the customer has already said the full amount is too much: the floor %s on that date, and say the rest stays overdue." % (money(full), speak(lbd), money(floor)))
        if attempts >= 2:
            t.append("  Attempt 2: the floor %s on the deadline %s." % (money(floor), speak(deadline)))
        t.append("  After attempt %d is refused: no further attempt. This product ends without a PTP (refused)." % attempts)
        lines.append("\n".join(t))
        present.append("Your %s has %s past due, %d days late." % (words, money(full), days))
    except Exception:
        pass

vars["product_count"] = str(count)
vars["products_text"] = "\n\n".join(lines) if lines else "No product data."
greet = "Thank you, " + str(vars.get("title") or "") + " " + str(vars.get("last_name") or "") + ", that is all verified. "
if count == 1:
    vars["present_text"] = greet + "I am calling from the collections team about a late payment. " + present[0] + " Can you make this payment today?"
elif count > 1:
    vars["present_text"] = greet + "I am calling from the collections team about late payments. " + " ".join(present) + " Can you make all of these payments today?"
else:
    vars["present_text"] = greet

# day table: today until a week past the latest deadline, at least three weeks
last = max(deadlines + [lbd, today + datetime.timedelta(days=21)]) + datetime.timedelta(days=7)
rows = []
d = today
while d <= last:
    w = WD[d.weekday()]
    say = []
    if d == today:
        say.append("today")
    if d == today + datetime.timedelta(days=1):
        say.append("tomorrow")
    if d == today + datetime.timedelta(days=2):
        say.append("the day after tomorrow")
    if monday <= d <= monday + datetime.timedelta(days=6) and d >= today:
        say.append("this " + w)
    if monday + datetime.timedelta(days=7) <= d <= monday + datetime.timedelta(days=13):
        say.append("next " + w)
    if 1 <= (d - today).days <= 7:
        say.append(w + " (said without this or next)")
    if d.day == 1 or (d + datetime.timedelta(days=1)).month != d.month:
        say.append("first of the month" if d.day == 1 else "last day of the month")
    if d in HOL:
        kind = "bank holiday, not a business day"
    elif d.weekday() >= 5:
        kind = "weekend, not a business day"
    else:
        kind = "business day"
    verdicts = []
    for i in range(1, count + 1):
        dl = datetime.date.fromisoformat(vars["p%d_deadline" % i])
        label = vars["p%d_words" % i] + ": " if count > 1 else "PTP: "
        if d > dl:
            verdicts.append(label + "NOT allowed, after the deadline; say the latest date is " + speak(dl) + " and offer it")
        elif not is_bd(d):
            verdicts.append(label + "NOT allowed; offer " + speak(next_bd_on_or_after(d)) + " instead")
        else:
            verdicts.append(label + "allowed")
    row = speak(d) + " | customer may say: " + (", ".join(say) if say else "-") + " | " + kind
    if verdicts:
        row += " | " + "; ".join(verdicts)
    rows.append(row)
    d = d + datetime.timedelta(days=1)
vars["day_table"] = "\n".join(rows)
'''

# ----------------------------------------------------------------------------- helpers

HEADERS = {"type": "object", "properties": {"Content-Type": {"type": "string", "default": "application/json"}}}


def api_tool(name, body_props, required, description="", retries=0, post=None):
    tool = {
        "type": "function",
        "config": {"timeoutMs": 12000, "maxRetries": retries},
        "function": {
            "name": name,
            "handler": "__function__:api_call",
            "description": description or name,
            "parameters": {"type": "object", "properties": {
                "url": {"type": "string", "default": f"{SERVER}/{name}"},
                "method": {"type": "string", "default": "POST"},
                "headers": HEADERS,
                "body": {"type": "object", "properties": {"customer_id": {"type": "string", "default": "{{customer_id}}"}, **body_props},
                         "required": required},
            }},
        },
    }
    if post:
        tool["post_process_code"] = post
    return tool


def always(target):
    return {"target_node": target, "description": "always", "condition": {"operator": "always"}}


def var_is(target, desc, *checks, logic="or"):
    conds = [{"variable": v, "operator": op, "operand": operand} for v, op, operand in checks]
    return {"target_node": target, "description": desc, "condition": {"logic": "or", "conditions": conds}}


def tool_move(target, desc):
    return {"target_node": target, "description": desc, "is_tool_call": True,
            "condition": {"operator": "matches_intent", "description": desc}}


def code_node(name, nxt):
    return {"name": name, "node_type": "code", "passthrough": True, "passthrough_default_transition": nxt,
            "on_enter": {"type": "silent"}, "disable_inactivity_monitor": True,
            "pre_actions": [{"type": "function", "function": {"name": "code_exec", "handler": "__function__:code_exec",
                                                              "parameters": {"type": "object", "properties": {
                                                                  "code": {"type": "string", "default": PLAN_CODE},
                                                                  "timeout_ms": {"type": "number", "default": 10000}}}}}],
            "transitions": [always(nxt)]}


def say_node(name, text, nxt, routes=()):
    """Passthrough step with a fixed line. Used for everything said before a bank action or the close."""
    return {"name": name, "node_type": "conversation", "passthrough": True, "passthrough_default_transition": nxt,
            "on_enter": {"type": "tts", "text": text}, "disable_inactivity_monitor": True,
            "task_message": "Do not call any tool in this turn.", "transitions": list(routes) + [always(nxt)]}


def router_node(name, routes, nxt):
    return {"name": name, "node_type": "conversation", "passthrough": True, "passthrough_default_transition": nxt,
            "on_enter": {"type": "silent"}, "disable_inactivity_monitor": True,
            "task_message": "Do not call any tool in this turn.", "transitions": list(routes) + [always(nxt)]}


def close_node(outcome, reason=None):
    body = {"outcome": {"type": "string", "enum": [outcome], "default": outcome}}
    if reason:
        body["reason"] = {"type": "string", "default": reason}
    name = "close_" + outcome + ("_" + reason if reason else "")
    tool = api_tool("close_call", body, ["customer_id", "outcome"], "Record how the call ended.", retries=2)
    return name, {"name": name, "node_type": "api_request", "passthrough": True, "passthrough_default_transition": "hang_up",
                  "on_enter": {"type": "silent"}, "disable_inactivity_monitor": True, "pre_actions": [tool],
                  "response_mapping": [], "transitions": [always("hang_up")]}


def transfer_node(queue, nxt):
    tool = api_tool("transfer_to_agent", {"queue": {"type": "string", "enum": [queue], "default": queue}},
                    ["customer_id", "queue"], "Hand the call to a person.", retries=1)
    name = "transfer_" + queue
    return name, {"name": name, "node_type": "api_request", "passthrough": True, "passthrough_default_transition": nxt,
                  "on_enter": {"type": "silent"}, "disable_inactivity_monitor": True, "pre_actions": [tool],
                  "response_mapping": [], "transitions": [always(nxt)]}


HANG_UP = {"name": "hang_up", "node_type": "end_call", "on_enter": {"type": "silent"}, "disable_inactivity_monitor": True,
           "transitions": [], "terminal": {"type": "function", "function": {
               "name": "call_closed", "handler": "__function__:end_call",
               "parameters": {"type": "object", "properties": {"message_mode": {"type": "string", "default": "none"}}}}}}

VERIFY_POST = r'''
try:
    if isinstance(result, dict):
        result.pop("header", None)
        d = result.get("data")
        if isinstance(d, dict):
            left = d.get("wrong_answers_left")
            if d.get("hint") == "day_month_swapped":
                msg = "Day and month look swapped. This is NOT a wrong answer. Ask the customer to say the month of birth as a word (for example March), then call verify_identity again with the corrected date."
            elif d.get("ok") is False:
                msg = "The answer could not be read. It is NOT counted as wrong. Ask for the same answer again: a date of birth with day, month and year, or the four last digits of the phone number."
            elif d.get("all_verified"):
                msg = "Both answers are verified. Say thank you."
            elif d.get("verified"):
                msg = "This answer is correct. Now ask the second security question: the last four digits of the phone number on file."
            elif left is not None and str(left) in ("0", "0.0"):
                msg = "Three wrong answers. The check has ended. Say nothing about the account."
            else:
                msg = "This answer is wrong. Wrong answers left: " + str(left) + ". Tell the customer it does not match and ask the same question again."
            d["what_to_do_next"] = msg
except Exception:
    pass
'''

SYSTEM = """You are the digital assistant of Freya Bank, on an outbound phone call. Speak English. Keep every turn to one or two short sentences. Address the customer as {{title}} {{last_name}}.

Rules for the whole call:
- Never improvise. Never offer a discount, a waiver, an instalment plan or any term that is not in your instructions.
- If the customer asks something your information does not answer, say you do not have that information. Never invent figures, dates or reasons.
- "Is this a scam?": say they can verify this call by phoning Freya Bank's customer service number, then go on with your task.
- "Am I talking to a robot / an AI?": say you are Freya Bank's digital assistant, then go on with your task.
- Never work out a date, a weekday, a deadline or a count yourself. Look it up in the tables you are given.
- Never say that a promise is "recorded" unless create_promise returned ok true for it in this call. Do not use the word "recorded" in any other sentence.
- When a tool call fails, say so honestly. Never claim something was done when it was not.
- Call at most one tool per message. After every tool result, speak to the customer or call the next tool. Never end a turn with nothing.
- Tools named transition_to_... move the call on. Call one only when its description fits, and never together with another tool.
"""

PRE_VERIFY = """Until the security check is passed you must not say "collections", "debt", "payment", "overdue", any amount or any product, to anyone, relatives included. If asked what the call is about, say you can explain once you have confirmed you are speaking with the right person."""

OPENING_TEXT = ("Hello, I am a digital assistant calling from Freya Bank, and we keep an audio recording of this call. "
                "Am I speaking with {{title}} {{last_name}}?")


def common_nodes(after_verify):
    """Opening, someone else, security. Shared by both briefs."""
    n = {}
    n["setup"] = code_node("setup", "opening")
    n["opening"] = {
        "name": "opening", "node_type": "conversation",
        "on_enter": {"type": "tts", "text": OPENING_TEXT}, "on_enter_first_entry_only": True,
        "task_message": f"""You have said that you are a digital assistant calling from Freya Bank, that the call is recorded, and asked "Am I speaking with {{{{title}}}} {{{{last_name}}}}?". Your job is to find out who answered.
{PRE_VERIFY}
Do not call any bank tool in this step.

How to judge each answer:
- Only "yes", "that's me", "speaking", or the customer's own name ({{{{first_name}}}} or {{{{last_name}}}}) confirm. Then call transition_to_security.
- "Hello", "go ahead", "who is this", "what is this about" do not confirm. Ask once more: "Am I speaking with {{{{title}}}} {{{{last_name}}}}?". This is the second ask.
- A robot or scam question: answer it (see the general rules) and, in the same turn, ask "Am I speaking with {{{{title}}}} {{{{last_name}}}}?" again. That ask counts as the second ask.
- If it is still unclear who answered after the second ask, call transition_to_bye_unclear.
- Someone else answers or says the customer is not available (a relative, a colleague, "he is not here"): call transition_to_third_party. Say nothing about why you are calling.
- "This number does not belong to that person" / wrong number: call transition_to_bye_wrong_number.
- The customer has died: call transition_to_bye_deceased at once, without saying anything yourself.
- The person says they do not want to talk: ask once whether this is {{{{title}}}} {{{{last_name}}}}. If they say a second time that they do not want to talk, call transition_to_bye_declined.
- They ask for a human: first ask once whether you can help. If they insist, call transition_to_say_transfer_general.""",
        "max_node_turns": 8, "max_turn_transition": "bye_unclear",
        "transitions": [
            tool_move("security", "The person confirmed they are the customer: yes, that's me, speaking, or their own name."),
            tool_move("third_party", "Someone other than the customer answered, or the customer is not available."),
            tool_move("bye_wrong_number", "The number does not belong to the customer."),
            tool_move("bye_deceased", "The person says the customer has died."),
            tool_move("bye_unclear", "Still unclear who answered after the second ask."),
            tool_move("bye_declined", "The person said twice that they do not want to talk."),
            tool_move("say_transfer_general", "The person insists on speaking with a human after you asked once whether you can help."),
        ],
    }
    n["third_party"] = {
        "name": "third_party", "node_type": "conversation",
        "on_enter": {"type": "llm", "prompt": "If the person already said when {{title}} {{last_name}} can be reached, handle that time as described. Otherwise ask, in one short sentence, when {{title}} {{last_name}} can be reached."},
        "task_message": f"""Someone other than {{{{title}}}} {{{{last_name}}}} is on the line. Say nothing beyond your opening sentence and never say why you are calling. A relative may not answer security questions and is told nothing about the account, even if they offer to pay.
{PRE_VERIFY}

Your job: find out when the customer can be reached and book a callback.
{{{{today_text}}}}
Callback window (the only times you may book):
{{{{callback_text}}}}

- When the person gives a day and a time inside the window, call schedule_callback with the date (YYYY-MM-DD, from the window above) and the time (HH:MM, 24 hour).
- If the person offers a day or time outside the window, ask once for another time, and say which times are possible. If the second time is outside the window too, call transition_to_bye_no_callback. Never book outside the window.
- If they cannot or will not give a time, call transition_to_bye_no_callback.
- If schedule_callback fails, say so and try it once more. If it fails again, call transition_to_bye_no_callback.
- "This number does not belong to that person": call transition_to_bye_wrong_number.
- The customer has died: call transition_to_bye_deceased at once, without saying anything yourself.""",
        "tools": [api_tool("schedule_callback", {
            "date": {"type": "string", "default": "{{date}}", "description": "Callback date, YYYY-MM-DD, copied from the callback window."},
            "time": {"type": "string", "default": "{{time}}", "description": "Callback time, HH:MM, 24 hour."}},
            ["customer_id", "date", "time"], "Book a callback. CALL it as soon as the person gives a day and time inside the callback window.")],
        "max_node_turns": 10, "max_turn_transition": "bye_no_callback",
        "transitions": [
            var_is("bye_callback", "The callback was booked", ("schedule_callback_success_count", "greater_than", 0)),
            var_is("bye_no_callback", "Booking failed twice", ("schedule_callback_failure_count", "greater_than", 1)),
            tool_move("bye_no_callback", "No callback time inside the window: the second offered time was outside it too, or no time was given, or booking failed twice."),
            tool_move("bye_wrong_number", "The number does not belong to the customer."),
            tool_move("bye_deceased", "The customer has died."),
        ],
    }
    n["security"] = {
        "name": "security", "node_type": "conversation",
        "on_enter": {"type": "tts", "text": "Thank you. Before we go on, I need to ask you two security questions. First, what is your date of birth?"},
        "on_enter_first_entry_only": True,
        "task_message": f"""The person said they are {{{{title}}}} {{{{last_name}}}}. Your job is the security check.
{PRE_VERIFY}

- Ask two questions, one at a time: first the date of birth, then the last four digits of the phone number on file.
- CALL verify_identity for every answer. For the date of birth send field date_of_birth and the date as YYYY-MM-DD, whatever way the customer said it. A date given only in numbers is day, then month, then year (05/03/1980 is 1980-03-05). For the phone send field phone_last4 and the four digits.
- Follow the what_to_do_next line in each verify_identity result.
- A wrong answer may be asked again. The service counts wrong answers; never state the debt to someone who failed.
- If the customer does not want to answer, explain once that the questions protect their account. Asking what the call is about instead of answering counts as not wanting to answer. On the second refusal or the second such question, call transition_to_bye_declined.
- If they ask for a human: first ask once whether you can help. If they insist, call transition_to_say_transfer_general.
- A robot or scam question: answer it, then repeat your current question.""",
        "tools": [api_tool("verify_identity", {
            "field": {"type": "string", "enum": ["date_of_birth", "phone_last4"], "default": "{{field}}",
                      "description": "Which answer this is: date_of_birth or phone_last4."},
            "answer": {"type": "string", "default": "{{answer}}",
                       "description": "date_of_birth as YYYY-MM-DD; phone_last4 as four digits."}},
            ["customer_id", "field", "answer"], "Check one security answer. CALL it every time the customer gives an answer.",
            post=VERIFY_POST)],
        "max_node_turns": 20, "max_turn_transition": "bye_declined",
        "transitions": [
            var_is("load_account", "Both security answers verified",
                   ("verify_identity_response.data.all_verified", "equals", "true"),
                   ("verify_identity_response.data.all_verified", "equals", "True")),
            var_is("bye_failed", "Three wrong security answers",
                   ("verify_identity_response.data.wrong_answers_left", "equals", "0")),
            tool_move("bye_declined", "The customer refused the security questions a second time, or asked a second time what the call is about instead of answering."),
            tool_move("say_transfer_general", "The customer insists on speaking with a human after you asked once whether you can help."),
        ],
    }
    n["load_account"] = {
        "name": "load_account", "node_type": "api_request", "passthrough": True, "passthrough_default_transition": "plan",
        "on_enter": {"type": "silent"}, "disable_inactivity_monitor": True,
        "pre_actions": [api_tool("get_account", {}, ["customer_id"], "Get the late products.", retries=2)],
        "response_mapping": [{"path": "data.products", "variable": "products"}],
        "transitions": [always("plan")],
    }
    n["plan"] = code_node("plan", "check_account")
    n["check_account"] = router_node("check_account", [
        var_is("bye_no_account", "No product data", ("product_count", "equals", "0"))], after_verify)
    return n


def endings(name_by_title, promise_say):
    """Goodbye lines, transfers, close steps and the end step."""
    n = {}
    addr = "{{title}} {{last_name}}"
    bye = {
        "bye_callback": ("Thank you. We will call back at that time. Goodbye.", ("not_reached", "callback")),
        "bye_no_callback": ("Thank you for your time. Goodbye.", ("not_reached", "no_callback")),
        "bye_wrong_number": ("I apologise for the inconvenience. Thank you for your time. Goodbye.", ("not_reached", "wrong_number")),
        "bye_deceased": ("I am sorry for your loss. Thank you for your time. Goodbye.", ("not_reached", "deceased")),
        "bye_unclear": ("Thank you for your time. Goodbye.", ("not_reached", "unclear")),
        "bye_declined": ("I understand. Thank you for your time. Goodbye.", ("not_verified", "declined")),
        "bye_failed": ("I am sorry, I could not verify your identity. Please use the Freya Bank mobile app or visit a branch. Thank you for your time. Goodbye.", ("not_verified", "failed")),
        "bye_no_account": ("I am sorry, I cannot reach your account details right now because of a technical problem. Thank you for your time. Goodbye.", ("no_promise", "service_error")),
    }
    bye.update(name_by_title)
    for key, (text, (outcome, reason)) in bye.items():
        cname, cnode = close_node(outcome, reason)
        n[cname] = cnode
        n[key] = say_node(key, text, cname)
    cname, cnode = close_node("promise")
    n[cname] = cnode
    n["bye_promise"] = say_node("bye_promise", promise_say, cname)
    for queue, reason, line in (
            ("general", "human", f"Of course. I will connect you with a colleague now. Thank you for your time, {addr}. Goodbye."),
            ("restructuring", "restructuring", f"I will connect you with our team that handles payment plans now. Thank you for your time, {addr}. Goodbye."),
            ("support", "support", f"I will connect you with our customer support team now. Thank you for your time, {addr}. Goodbye.")):
        cname, cnode = close_node("transferred", reason)
        n[cname] = cnode
        tname, tnode = transfer_node(queue, cname)
        n[tname] = tnode
        n["say_transfer_" + queue] = say_node("say_transfer_" + queue, line, tname)
    n["hang_up"] = HANG_UP
    return n


DATE_RULES = """DATE RULES (use the day table; never work out a date or weekday yourself)
- A PTP date must be marked allowed in the day table for that product: today or later, a business day, not after the product's deadline.
- A weekend day or bank holiday not after the deadline: offer the business day the table gives instead.
- A date after the deadline: say the latest date you can take is the deadline and offer it. Refusing the deadline is a flat refusal.
- A vague period ("next week", "end of the month", "when my salary comes", "end of the week"): ask once for the exact day. If they still name none, propose the deadline.
- "next <weekday>" means that weekday in the following calendar week; "this <weekday>" means the one in the current week. The table lists these words for each day.

AMOUNT RULES
- Never ask "how much can you pay?". You propose every amount yourself, from the product facts.
- Ask for the full past-due amount first.
- "The full amount is too much": offer the floor once and say that the rest stays overdue. Refusing the floor is a flat refusal.
- An amount the customer proposes from the floor up to the full amount, both included, is accepted. Above the full amount: say you can take at most the full amount. Below the floor: say it cannot be accepted and offer the floor once; if they do not accept it, that is a flat refusal.

PERSUASION
- A date or an amount the customer proposes is never a refusal; check it with the rules above.
- A flat refusal or a non-answer uses one persuasion attempt. "No" to paying today, with no date and no amount, is a flat refusal.
- Make the attempts exactly as listed for the product, in order. When the product's attempts are used up, stop: never repeat an offer the customer already refused, and offer nothing new."""


