    n["record_promise"] = {
        "name": "record_promise", "node_type": "conversation",
        "on_enter": {"type": "llm", "prompt": "Call create_promise now with the amount and the date the customer just confirmed. Say nothing before the call."},
        "task_message": """The customer confirmed the read-back of the PTP. Your only job: CALL create_promise with the confirmed amount (a number, for example 120.50) and the confirmed date (YYYY-MM-DD, from the day table below).
- If create_promise fails (ok false or an error), call it once more right away with the same values.
- Never say the promise is recorded yourself. Do not say anything else in this step.

{{products_text}}
DAY TABLE
{{day_table}}""",
        "tools": [api_tool("create_promise", {
