def endings(name_by_title, promise_say):
    """Goodbye lines, transfers, close steps and the end step."""
    n = {}
    addr = "{{title}} {{last_name}}"
    bye = {
        "bye_callback": ("Thank you. We will call back at that time. Goodbye.", ("not_reached", "callback")),
        "bye_no_callback": ("Thank you for your time. Goodbye.", ("not_reached", "no_callback")),
        "bye_wrong_number": ("I apologise for the inconvenience. Thank you for your time. Goodbye.", ("not_reached", "wrong_number")),
        "bye_deceased": ("I am sorry for your loss. Thank you for your time. Goodbye.", ("not_reached", "deceased")),
        "bye_unclear": ("Thank you for your time. Goodbye.", ("not_reached", "unclear")),
        "bye_declined": ("I understand. Thank you for your time. Goodbye.", ("not_verified", "declined")),
        "bye_failed": ("I am sorry, I could not verify your identity. Please use the Freya Bank mobile app or visit a branch. Thank you for your time. Goodbye.", ("not_verified", "failed")),
        "bye_no_account": ("I am sorry, I cannot reach your account details right now because of a technical problem. Thank you for your time. Goodbye.", ("no_promise", "service_error")),
    }
    bye.update(name_by_title)
    for key, (text, (outcome, reason)) in bye.items():
        cname, cnode = close_node(outcome, reason)
        n[cname] = cnode
        n[key] = say_node(key, text, cname)
    cname, cnode = close_node("promise")
    n[cname] = cnode
    n["bye_promise"] = say_node("bye_promise", promise_say, cname)
    for queue, reason, line in (
            ("general", "human", f"Of course. I will connect you with a colleague now. Thank you for your time, {addr}. Goodbye."),
            ("restructuring", "restructuring", f"I will connect you with our team that handles payment plans now. Thank you for your time, {addr}. Goodbye."),
            ("support", "support", f"I will connect you with our customer support team now. Thank you for your time, {addr}. Goodbye.")):
        cname, cnode = close_node("transferred", reason)
        n[cname] = cnode
        tname, tnode = transfer_node(queue, cname)
        n[tname] = tnode
        n["say_transfer_" + queue] = say_node("say_transfer_" + queue, line, tname)
    n["hang_up"] = HANG_UP
    return n


DATE_RULES = """DATE RULES (use the day table; never work out a date or weekday yourself)
- A PTP date must be marked allowed in the day table for that product: today or later, a business day, not after the product's deadline.
- A weekend day or bank holiday not after the deadline: offer the business day the table gives instead.
- A date after the deadline: say the latest date you can take is the deadline and offer it. Refusing the deadline is a flat refusal.
- A vague period ("next week", "end of the month", "when my salary comes", "end of the week"): ask once for the exact day. If they still name none, propose the deadline.
- "next <weekday>" means that weekday in the following calendar week; "this <weekday>" means the one in the current week. The table lists these words for each day.

AMOUNT RULES
- Never ask "how much can you pay?". You propose every amount yourself, from the product facts.
- Ask for the full past-due amount first.
- "The full amount is too much": offer the floor once and say that the rest stays overdue. Refusing the floor is a flat refusal.
- An amount the customer proposes from the floor up to the full amount, both included, is accepted. Above the full amount: say you can take at most the full amount. Below the floor: say it cannot be accepted and offer the floor once; if they do not accept it, that is a flat refusal.

PERSUASION
- A date or an amount the customer proposes is never a refusal; check it with the rules above.
- A flat refusal or a non-answer uses one persuasion attempt. "No" to paying today, with no date and no amount, is a flat refusal.
- Make the attempts exactly as listed for the product, in order. When the product's attempts are used up, stop: never repeat an offer the customer already refused, and offer nothing new."""


